{
  "command": "curl -s -m 20 -A 'Mozilla/5.0' -o /tmp/cna_home.html -w '%{http_code}|%{content_type}\\n' \"https://www.cna.com.tw/\" 2>/dev/null\ngrep -oE 'href=\"[^\"]*(rss|feed)[^\"]*\"' /tmp/cna_home.html -i | sort -u | head -30\necho \"---also check RSS icon links---\"\ngrep -oE '(rss|feed)[^\"]{0,60}' /tmp/cna_home.html -i | sort -u | head -30",
  "timeout": 60
}

{
  "command": "curl -s -m 20 -A 'Mozilla/5.0' -o /tmp/cna_rss_page.html -w 'CNA rss page: %{http_code}|%{content_type}\\n' \"https://www.cna.com.tw/about/rss.aspx\" 2>/dev/null\necho \"=== RSS links on page ===\"\ngrep -oE 'href=\"[^\"]*\"' /tmp/cna_rss_page.html -i | grep -iE 'xml|rss' | sort -u | head -40",
  "timeout": 60
}

{
  "command": "curl -s -m 15 -A 'Mozilla/5.0' \"https://news.ltn.com.tw/rss/politics.xml\" | head -c 3 | xxd\ncurl -s -L -m 15 -A 'Mozilla/5.0' \"https://abcnews.go.com/abcnews/topstories\" | head -c 3 | xxd\ncurl -s -m 15 -A 'Mozilla/5.0' \"https://feeds.feedburner.com/rsscna/politics\" | head -c 3 | xxd",
  "timeout": 60
}
